CREATE OR REPLACE FUNCTION public.get_timeline_activity_page(p_entity_kind text, p_entity_id uuid, p_since timestamptz DEFAULT NULL, p_until timestamptz DEFAULT NULL, p_categories text[] DEFAULT NULL, p_assignees uuid[] DEFAULT NULL, p_include_unassigned boolean DEFAULT false, p_search text DEFAULT NULL, p_cursor_at timestamptz DEFAULT NULL, p_cursor_id uuid DEFAULT NULL, p_page_size integer DEFAULT 40) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path = public AS $$ DECLARE v_limit integer := LEAST(GREATEST(COALESCE(p_page_size,40),1),100); v_result jsonb; BEGIN IF p_entity_kind NOT IN ('lead','contact','company','deal','ticket') THEN RAISE EXCEPTION 'invalid entity kind'; END IF; IF (p_cursor_at IS NULL) <> (p_cursor_id IS NULL) THEN RAISE EXCEPTION 'cursor timestamp and id must be provided together'; END IF; WITH scoped AS MATERIALIZED (SELECT a.id,a.type,a.subject,a.body,a.hs_createdate,a.created_at,a.activity_date,a.due_date,a.completed,a.owner_id,a.assigned_to,a.external_ids,a.attachments,a.meeting_location,a.related_lead_id,a.related_contact_id,a.related_company_id,a.related_deal_id,a.related_ticket_id,COALESCE(a.hs_createdate,a.created_at) effective_at,CASE WHEN a.type IN ('call','email','whatsapp','task','meeting','survey') THEN a.type::text WHEN a.type IN ('sms','linkedin_message','postal_mail') THEN 'message' ELSE 'note' END category FROM public.activities a WHERE a.deleted_at IS NULL AND CASE p_entity_kind WHEN 'lead' THEN a.related_lead_id=p_entity_id WHEN 'contact' THEN a.related_contact_id=p_entity_id WHEN 'company' THEN a.related_company_id=p_entity_id WHEN 'deal' THEN a.related_deal_id=p_entity_id WHEN 'ticket' THEN a.related_ticket_id=p_entity_id ELSE false END AND (p_since IS NULL OR COALESCE(a.hs_createdate,a.created_at)>=p_since) AND (p_until IS NULL OR COALESCE(a.hs_createdate,a.created_at)<p_until) AND (p_categories IS NULL OR cardinality(p_categories)=0 OR CASE WHEN a.type IN ('call','email','whatsapp','task','meeting','survey') THEN a.type::text WHEN a.type IN ('sms','linkedin_message','postal_mail') THEN 'message' ELSE 'note' END=ANY(p_categories)) AND ((COALESCE(cardinality(p_assignees),0)=0 AND NOT COALESCE(p_include_unassigned,false)) OR (COALESCE(cardinality(p_assignees),0)>0 AND COALESCE(a.assigned_to,a.owner_id)=ANY(p_assignees)) OR (COALESCE(p_include_unassigned,false) AND COALESCE(a.assigned_to,a.owner_id) IS NULL)) AND (NULLIF(btrim(p_search),'') IS NULL OR concat_ws(' ',a.subject,a.body) ILIKE '%'||p_search||'%' OR EXISTS (SELECT 1 FROM public.email_messages em WHERE em.id=CASE WHEN (a.external_ids->>'email_message_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN (a.external_ids->>'email_message_id')::uuid ELSE NULL END AND concat_ws(' ',em.from_name,em.from_email,em.subject,em.body_text,em.body_html) ILIKE '%'||p_search||'%'))), counts AS (SELECT COALESCE(sum(n),0)::bigint total,COALESCE(jsonb_object_agg(category,n),'{}'::jsonb) categories FROM (SELECT category,count(*)::bigint n FROM scoped GROUP BY category)c), page_plus AS (SELECT * FROM scoped WHERE p_cursor_at IS NULL OR (effective_at,id)<(p_cursor_at,p_cursor_id) ORDER BY effective_at DESC,id DESC LIMIT v_limit+1), page AS (SELECT * FROM page_plus ORDER BY effective_at DESC,id DESC LIMIT v_limit), tail AS (SELECT effective_at,id FROM page ORDER BY effective_at ASC,id ASC LIMIT 1) SELECT jsonb_build_object('items',COALESCE((SELECT jsonb_agg(to_jsonb(p)-'effective_at'-'category' ORDER BY effective_at DESC,id DESC) FROM page p),'[]'::jsonb),'total',COALESCE((SELECT total FROM counts),0),'counts',COALESCE((SELECT categories FROM counts),'{}'::jsonb),'has_more',(SELECT count(*)>v_limit FROM page_plus),'next_at',CASE WHEN (SELECT count(*)>v_limit FROM page_plus) THEN (SELECT effective_at FROM tail) ELSE NULL END,'next_id',CASE WHEN (SELECT count(*)>v_limit FROM page_plus) THEN (SELECT id FROM tail) ELSE NULL END) INTO v_result; RETURN v_result; END; $$; GRANT EXECUTE ON FUNCTION public.get_timeline_activity_page(text,uuid,timestamptz,timestamptz,text[],uuid[],boolean,text,timestamptz,uuid,integer) TO authenticated; GRANT EXECUTE ON FUNCTION public.get_timeline_activity_page(text,uuid,timestamptz,timestamptz,text[],uuid[],boolean,text,timestamptz,uuid,integer) TO service_role;